<script setup lang="ts">
import {ref} from 'vue';import {request} from './service';
defineProps({modelValue:{type:String,default:''},label:{type:String,default:'背景图片'},clearable:{type:Boolean,default:true}});const emit=defineEmits(['update:modelValue']);const busy=ref(false),error=ref('');
const images=[['landscape-fields','水田晚霞'],['landscape-dawn','云海初光'],['landscape-study','夜间书桌'],['landscape-room','午后书房'],['landscape-fantasy','幻境旅路'],['landscape-eye','瞳孔晚霞'],['landscape-games','游戏存档'],['dimension-blue','晴空序章'],['dimension-sunset','落日来信'],['dimension-violet','紫色回响']];
async function upload(e){const file=e.target.files?.[0];if(!file)return;error.value='';busy.value=true;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('请选择 8MB 以内的 PNG、JPEG 或 WebP 图片');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const r=await request('/api/studio/upload','POST',{data});emit('update:modelValue',r.url);}catch(e){error.value=e.message;}finally{busy.value=false;e.target.value='';}}
</script>
<template><div class="image-picker"><div class="picker-current"><img v-if="modelValue" :src="modelValue" :alt="label"/><span v-else>使用默认外观</span><label class="picker-upload">{{busy?'上传中…':'上传自己的图片'}}<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" :aria-label="'上传'+label" @change="upload"/></label><button v-if="clearable && modelValue" type="button" @click="emit('update:modelValue','')">恢复默认</button></div><div class="picker-presets"><button v-for="[id,name] in images" :key="id" type="button" :aria-label="name" :aria-pressed="modelValue==='/assets/'+id+'.webp'" @click="emit('update:modelValue','/assets/'+id+'.webp')"><img :src="'/assets/'+id+'.webp'" :alt="name" loading="lazy"/><span>{{name}}</span></button></div><p v-if="error" role="alert">{{error}}</p></div></template>
<style scoped>.image-picker{width:100%}.picker-current{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:16px}.picker-current>img{width:130px;height:76px;object-fit:cover;border-radius:8px}.picker-current>span{font-size:12px;color:var(--studio-muted)}.picker-upload,.picker-current>button{border:1px solid var(--studio-line);border-radius:6px;padding:9px 12px;font-size:12px;color:var(--studio-ink);background:var(--studio-panel);cursor:pointer}.picker-upload input{display:block;max-width:190px;margin-top:8px;font-size:11px}.picker-presets{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.picker-presets button{padding:3px;border:2px solid transparent;border-radius:7px;background:none;color:inherit;cursor:pointer;min-width:0}.picker-presets button[aria-pressed=true]{border-color:#9481ac}.picker-presets img{display:block;width:100%;height:65px;object-fit:cover;border-radius:4px}.picker-presets span{font-size:10px;display:block;margin-top:5px}.image-picker>p{color:#b34848;font-size:12px}@media(max-width:600px){.picker-presets{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>
